#!/usr/bin/env python3
"""Paired frozen-binary JSON diagnostics, with full oracles and provenance."""
import argparse
import hashlib
import importlib.util
import json
from pathlib import Path
import statistics
import subprocess

ALT = Path('/Users/0x1/Documents/htdocs/altbak.pub-gopurs')
spec = importlib.util.spec_from_file_location('diagnostic', ALT / 'bin/benchmark/json-diagnostic.py')
diagnostic = importlib.util.module_from_spec(spec)
spec.loader.exec_module(diagnostic)


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument('--suite', required=True, choices=diagnostic.SUITES)
    parser.add_argument('--before', type=Path, required=True)
    parser.add_argument('--after', type=Path, required=True)
    parser.add_argument('--output', type=Path, required=True)
    parser.add_argument('--pairs', type=int, default=5)
    args = parser.parse_args()
    args.output.mkdir(parents=True, exist_ok=False)
    workspaces = {'before': args.before.resolve(), 'after': args.after.resolve()}
    manifests = {name: json.loads((work / 'manifest.json').read_text()) for name, work in workspaces.items()}
    for name, work in workspaces.items():
        diagnostic.check_suite(manifests[name], args.suite)
        for filename, key in [('benchmark', 'binary_sha256'), ('benchmark.mjs', 'js_sha256')]:
            if diagnostic.sha(work / filename) != manifests[name][key]:
                raise ValueError(f'Frozen {name} artifact changed: {filename}')
    if manifests['after']['sources'] != diagnostic.fingerprint(args.suite):
        raise ValueError('Treatment sources no longer match the manifest')
    raw, corpus_info = diagnostic.corpus_data(args.suite)
    corpus = args.output.resolve() / 'corpus.json'
    corpus.write_bytes(raw)
    oracle = json.loads((diagnostic.fixtures(args.suite) / 'expected.json').read_text())
    env = diagnostic.environment()
    env['DIAG_CORPUS'] = str(corpus)
    results = {name: {'go': [], 'js': []} for name in workspaces}
    identical_js = manifests['before']['js_sha256'] == manifests['after']['js_sha256']

    def run(name, runtime, index):
        work = workspaces[name]
        command = [str(work / 'benchmark')] if runtime == 'go' else ['node', str(work / 'benchmark.mjs')]
        output = subprocess.check_output(command, cwd=work, env=env, text=True)
        (args.output / f'{index}-{name}-{runtime}.json').write_text(output)
        report = json.loads(output)
        diagnostic.validate_result(report, oracle, args.suite)
        results[name][runtime].append(report)
        print(name, runtime, {p: round(report['phases'][p]['time_us'] / 1000, 3) for p in ['parse', 'decode', 'combined']}, flush=True)

    for index in range(args.pairs):
        for name in (['before', 'after'] if index % 2 == 0 else ['after', 'before']):
            run(name, 'go', index)
        if index < 3:
            if not identical_js:
                run('before', 'js', index)
            run('after', 'js', index)
    if manifests['after']['sources'] != diagnostic.fingerprint(args.suite):
        raise ValueError('Treatment sources changed during measurement')
    summary = {}
    for name, backends in results.items():
        summary[name] = {}
        for runtime, runs in backends.items():
            if not runs:
                continue
            summary[name][runtime] = {
                phase: {
                    'median_ms': statistics.median(r['phases'][phase]['time_us'] for r in runs) / 1000,
                    'process_ms': [r['phases'][phase]['time_us'] / 1000 for r in runs],
                    **({'allocated_bytes': statistics.median(s['allocated_bytes'] for r in runs for s in r['phases'][phase]['samples'])} if runtime == 'go' else {})
                } for phase in ['parse', 'decode', 'combined']
            }
    report = {
        'suite': args.suite, 'protocol': {'pairs': args.pairs, 'GOMAXPROCS': 1, 'GOGC': 100, 'PGO': False,
        'cell': 'median of process minima', 'js_identical': identical_js},
        'corpus': corpus_info, 'corpus_sha256': hashlib.sha256(raw).hexdigest(),
        'summary': summary, 'results': results, 'builds': manifests,
        'binary_bytes': {name: (work / 'benchmark').stat().st_size for name, work in workspaces.items()},
    }
    (args.output / 'results.json').write_text(json.dumps(report, indent=2) + '\n')
    print(json.dumps(summary, indent=2), flush=True)


if __name__ == '__main__':
    main()
